const input = $input.first().json || {};
const plan = input.responsePlan || {};
const fallbackText = String(input.fallbackText || input.text || '').trim();

if (!fallbackText) throw new Error('CASE002_RESPONSE_RENDERER_FALLBACK_MISSING');

const sourceInput = {
  tenantId: String(input.tenantId || ''),
  providerPhoneNumberId: String(input.providerPhoneNumberId || ''),
  senderId: String(input.senderId || input.to || ''),
  to: String(input.to || input.senderId || ''),
  providerMessageId: String(input.providerMessageId || ''),
  traceId: String(input.traceId || input.providerEventId || input.providerMessageId || ''),
  businessActionId: String(input.businessActionId || ''),
  idempotencyKey: String(input.idempotencyKey || ''),
  fallbackText,
  responsePlan: plan
};

const policy = [
  'You render customer-facing WhatsApp replies for CASE-002, an automotive workshop intake flow in Peru.',
  'Business decisions are already made by deterministic policy. You are a language renderer only.',
  'Rewrite the supplied fallbackText so it sounds natural, warm, feminine, attentive and confident, like a real workshop receptionist on WhatsApp.',
  'Do not explicitly state a gender. Do not force femininity through stereotypes, flirtation, cutesy diminutives, pet names, hearts, wink emojis, or exaggerated slang.',
  'Use clear natural Spanish suitable for Peru. Prefer neutral everyday wording over forced slang such as "buenazo" or "no caché".',
  'Keep it concise and conversational. Usually 1 to 5 short lines.',
  'Do not invent, remove, reinterpret or change any business fact, appointment status, availability, date, time, plate, price, safety statement or requested action.',
  'Every string in protectedFacts MUST appear verbatim in the reply when protectedFacts is non-empty.',
  'Do not mention internal implementation terms such as piloto, Level-2, sandbox, workflow, Gemini, internal calendar, provider, node, model or API.',
  'Do not diagnose mechanical problems or say a vehicle is safe to drive.',
  'Do not add emojis by default. Use none unless the fallback meaning clearly benefits from one; never use flirtatious emojis.',
  'Return only the structure requested by the output parser.'
].join('\n');

const prompt = policy + '\n\nRESPONSE_PLAN_JSON:\n' + JSON.stringify({
  action: String(plan.action || 'reply'),
  fallbackText,
  protectedFacts: Array.isArray(plan.protectedFacts) ? plan.protectedFacts : [],
  forbiddenTerms: Array.isArray(plan.forbiddenTerms) ? plan.forbiddenTerms : []
});

return [{ json: { sourceInput, prompt } }];

const source = $('Build Gemini Response Prompt').first().json.sourceInput || {};
const current = $input.first().json || {};

if (current.error) {
  return [{ json: { ...source, rendererMeta: { ok: false, provider: 'gemini', error: String(current.error).slice(0, 500) } } }];
}

const parsed = current.output && typeof current.output === 'object' ? current.output : current;
const rendered = String(parsed?.text || '').trim();
if (!rendered || rendered.length > 1200) {
  return [{ json: { ...source, rendererMeta: { ok: false, provider: 'gemini', error: 'INVALID_RENDERED_REPLY' } } }];
}

return [{
  json: {
    ...source,
    renderedReply: rendered,
    rendererMeta: {
      ok: true,
      provider: 'gemini',
      model: 'models/gemini-2.5-flash'
    }
  }
}];
